#
# Checks commit messages, and pull request titles and descriptions, against the rules of the team:
# - a co-author trailer may only name a team member, with the GitHub noreply address of the member;
# - no "Generated with" or "Generated by" line;
# - no robot pictogram.
#
# Usage:
#   .github/scripts/check-commit-messages.sh --range <base>..<head>   every commit of a range (pull request check)
#   .github/scripts/check-commit-messages.sh --file <message-file>    one commit message (commit-msg hook)
#   .github/scripts/check-commit-messages.sh --text <text> [label]    a pull request title or description

set -euo pipefail

TEAM=(
  "152161435+magloire04@users.noreply.github.com"
  "80360009+princespecial@users.noreply.github.com"
  "123805165+silveriomen@users.noreply.github.com"
  "136495514+tobi3h@users.noreply.github.com"
)

problems=0

# Reads a text on standard input and reports every line that breaks a rule.
check_text() {
  local label="$1" skip_comments="${2:-no}" line email member ok
  while IFS= read -r line || [ -n "$line" ]; do
    line="${line%$'\r'}"
    if [ "$skip_comments" = yes ] && [[ "$line" == \#* ]]; then
      continue
    fi
    if printf '%s' "$line" | grep -qiE '^[[:space:]]*co-authored-by:'; then
      email="$(printf '%s' "$line" | sed -nE 's/.*<([^>]+)>.*/\1/p' | tr '[:upper:]' '[:lower:]')"
      ok=no
      for member in "${TEAM[@]}"; do
        if [ "$email" = "$member" ]; then
          ok=yes
        fi
      done
      if [ "$ok" = no ]; then
        echo "$label: co-author outside the team: $line"
        problems=$((problems + 1))
      fi
    fi
    if printf '%s' "$line" | grep -qiE 'generated (with|by)'; then
      echo "$label: generation notice: $line"
      problems=$((problems + 1))
    fi
    if printf '%s' "$line" | grep -q '🤖'; then
      echo "$label: robot pictogram: $line"
      problems=$((problems + 1))
    fi
  done
}

case "${1:-}" in
  --range)
    for sha in $(git rev-list "$2"); do
      check_text "commit ${sha:0:7}" < <(git log -1 --format=%B "$sha")
    done
    ;;
  --file)
    check_text "commit message" yes < "$2"
    ;;
  --text)
    check_text "${3:-text}" <<< "$2"
    ;;
  *)
    echo "usage: $0 --range <base>..<head> | --file <message-file> | --text <text> [label]" >&2
    exit 2
    ;;
esac

if [ "$problems" -gt 0 ]; then
  echo "$problems problem(s) found." >&2
  echo "Each commit is written by the member who makes it. Remove these lines (git commit --amend for the last" >&2
  echo "commit, git rebase -i for older ones, or edit the pull request description), then push again." >&2
  exit 1
fi
echo "Commit messages: OK"
